import org.javatuples.Pair;

public class PhysicsEngine {
    private final double gravity;
    private Pair<Double, Double> position;
    private Pair<Double, Double> velocity;

    public PhysicsEngine() {
        this.gravity = 9.81; // Acceleration due to gravity
        this.position = Pair.with(0.0, 0.0);
        this.velocity = Pair.with(0.0, 0.0);
    }

    public void update(double g) {
        this.gravity = g;
        this.position = Pair.with(this.position.getValue(0) + this.velocity.getValue(0), this.position.getValue(1) + this.velocity.getValue(1));
        this.velocity = Pair.with(this.velocity.getValue(0) * g, this.velocity.getValue(1));
    }

    public Pair<Double, Double> getPosition() {
        return position;
    }

    public Pair<Double, Double> getVelocity() {
        return velocity;
    }
}
